do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 1';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 1', 0, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 0, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · Health matters</h2><p>Сегодня — здоровье: как сказать по-английски, что болит.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'flashcards', $blk${"title": "Повторяем слова урока. Нажми на карточку — услышишь слово и увидишь перевод", "cards": [{"text": "a cold", "translation": "простуда", "audio": "", "audio_tts": {"text": "a cold.", "voice": "en_GB-alba"}}, {"text": "a cough", "translation": "кашель", "audio": "", "audio_tts": {"text": "a cough.", "voice": "en_GB-alba"}}, {"text": "a headache", "translation": "головная боль", "audio": "", "audio_tts": {"text": "a headache.", "voice": "en_GB-alba"}}, {"text": "a blocked nose", "translation": "заложенный нос", "audio": "", "audio_tts": {"text": "a blocked nose.", "voice": "en_GB-alba"}}, {"text": "a runny nose", "translation": "насморк", "audio": "", "audio_tts": {"text": "a runny nose.", "voice": "en_GB-alba"}}, {"text": "a sore throat", "translation": "больное горло", "audio": "", "audio_tts": {"text": "a sore throat.", "voice": "en_GB-alba"}}, {"text": "a stomachache", "translation": "боль в животе", "audio": "", "audio_tts": {"text": "a stomachache.", "voice": "en_GB-alba"}}, {"text": "a temperature", "translation": "температура", "audio": "", "audio_tts": {"text": "a temperature.", "voice": "en_GB-alba"}}, {"text": "earache", "translation": "боль в ухе", "audio": "", "audio_tts": {"text": "earache.", "voice": "en_GB-alba"}}, {"text": "toothache", "translation": "зубная боль", "audio": "", "audio_tts": {"text": "toothache.", "voice": "en_GB-alba"}}, {"text": "the flu", "translation": "грипп", "audio": "", "audio_tts": {"text": "the flu.", "voice": "en_GB-alba"}}, {"text": "to sneeze", "translation": "чихать", "audio": "", "audio_tts": {"text": "to sneeze.", "voice": "en_GB-alba"}}, {"text": "I feel terrible", "translation": "мне очень плохо", "audio": "", "audio_tts": {"text": "I feel terrible.", "voice": "en_GB-alba"}}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай плакат о здоровье и выбери правильное слово", "questions": [{"q": "Always ___ your teeth after a meal.", "type": "single", "correct": [0], "options": [{"text": "brush"}, {"text": "wash"}]}, {"q": "Clean teeth can stop ___.", "type": "single", "correct": [1], "options": [{"text": "earache"}, {"text": "toothache"}]}, {"q": "Always put your hand in front of your mouth when you ___.", "type": "single", "correct": [1], "options": [{"text": "sneeze"}, {"text": "cough"}]}, {"q": "And put it in front of your nose and mouth when you ___.", "type": "single", "correct": [0], "options": [{"text": "sneeze"}, {"text": "cough"}]}, {"q": "Don’t give everyone your ___!", "type": "single", "correct": [1], "options": [{"text": "headache"}, {"text": "cold"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай про семью Джо у врача и перетащи слова в пропуски", "mode": "drag", "text": "This is Joe and his family. They all have health problems today and they are at the doctor's.\nJoe is very hot, so he has got __a temperature__.\nHis mum is drinking tea because she has got __a sore throat__.\nHis dad can't eat anything because his tooth hurts: he has got __toothache__.\nHis grandma is holding her ear, so she has got __earache__.\nHis sister, Penny, is holding her head because she has got __a headache__.\nAnd what about Rex, the dog? He is sneezing all the time: he has got __a runny nose__. The doctor looks surprised!"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Марка и Тины и перетащи слова в пропуски", "mode": "drag", "text": "Mark: Hi Tina. I'm phoning you because I can't come to play the new computer game today. I feel __terrible__. I've got a sore __throat__ and I'm __coughing__ all the time.\nTina: Oh dear. But it's OK, because I __feel__ bad too. I'm __hot__ because I've got a __temperature__.\nMark: I'm going to __drink__ lots of tea with honey.\nTina: Good idea. I'm going to __go__ to bed and sleep.\nMark: Bye then. Sleep well.\nTina: Thanks. Bye."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'exact_input', $blk${"title": "Прочитай предложение и напиши слово по-английски", "items": [{"prompt": "I'm sorry, but I can't come to the park. I've got a c… (простуда)", "accept": ["cold", "a cold", "Cold"]}, {"prompt": "I can't smell anything because I've got a b… n… (заложенный нос)", "accept": ["blocked nose", "a blocked nose", "Blocked nose"]}, {"prompt": "I ate too many pancakes and now I've got a s… (боль в животе)", "accept": ["stomachache", "a stomachache", "stomach ache", "Stomachache"]}, {"prompt": "I can't talk a lot today because I've got a c… (кашель)", "accept": ["cough", "a cough", "Cough"]}, {"prompt": "My ear hurts. I've got e… (боль в ухе)", "accept": ["earache", "an earache", "Earache"]}, {"prompt": "I'm very hot. I've got a t… (температура)", "accept": ["temperature", "a temperature", "Temperature"]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи, что у тебя бывает часто, что иногда, а чего не бывает никогда: <i>I often have … I sometimes have … I never have …</i> Три-четыре предложения.</p>", "sample": "", "sample_tts": {"text": "My little brother often has earache.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_star.webp\" alt=\"\" style=\"height:200px\"></p><p>Готово! Теперь ты можешь объяснить врачу, что у тебя болит.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 2';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 2', 1, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 1, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · have to</h2><p>Сегодня — как сказать по-английски «придётся» и «можно не».</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай письмо Эммы и выбери правильную форму", "questions": [{"q": "Gran says I ___ stay at home tomorrow.", "type": "single", "correct": [0], "options": [{"text": "have to"}, {"text": "has to"}]}, {"q": "I'm happy because I ___ go to school.", "type": "single", "correct": [0], "options": [{"text": "don't have to"}, {"text": "doesn't have to"}]}, {"q": "But we ___ finish our project.", "type": "single", "correct": [1], "options": [{"text": "has to"}, {"text": "have to"}]}, {"q": "Don't worry, you ___ come here.", "type": "single", "correct": [1], "options": [{"text": "doesn't have to"}, {"text": "don't have to"}]}, {"q": "Is 4 p.m. OK or ___ go out then?", "type": "single", "correct": [1], "options": [{"text": "you have to"}, {"text": "do you have to"}]}, {"q": "Gran says she ___ use the computer.", "type": "single", "correct": [0], "options": [{"text": "has to"}, {"text": "have to"}]}], "material": "<p><b>Hi Poppy,</b></p><p>I've got a sore throat and a runny nose, so Gran says I have to stay at home tomorrow. I'm happy because I don't have to go to school. But we have to finish our project. Don't worry, you don't have to come here. We can chat online – is 4 p.m. OK or do you have to go out then? I can't chat before that because Gran says she has to use the computer.</p><p><b>Emma</b></p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини вопрос с ответом", "pairs": [{"left": "Does Karen have to see the dentist?", "right": "Yes, she does. She has got toothache."}, {"left": "Do we have to go to bed now?", "right": "No, you don't. It isn't late."}, {"left": "Does Dad have to go to work?", "right": "No, he doesn't. It's Sunday."}, {"left": "Do they have to do any homework today?", "right": "Yes, they do."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь предложения с have to", "items": [{"words": ["I", "don't", "have", "to", "go", "to", "school", "on", "Saturday."], "sentence": "I don't have to go to school on Saturday.", "prompt": "в субботу школы нет"}, {"words": ["My", "mum", "has", "to", "cook", "every", "day."], "sentence": "My mum has to cook every day.", "prompt": "мама и готовка"}, {"words": ["My", "best", "friend", "has", "to", "get", "the", "bus", "home", "from", "school."], "sentence": "My best friend has to get the bus home from school.", "prompt": "друг и автобус"}, {"words": ["I", "don't", "have", "to", "do", "chores", "when", "I've", "got", "a", "headache."], "sentence": "I don't have to do chores when I've got a headache.", "prompt": "дела по дому и головная боль"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши have to в нужной форме с глаголом: brush · go · not go · not use · not wear · see", "mode": "type", "text": "Jane has got the flu. She __has to go__ to bed.\nIt's Saturday. I __don't have to go__ to school. Hurray!\nFred ate an ice cream. He __has to brush__ his teeth, but he can't find his toothbrush!\nDon't worry about wet hair. It's hot today! You __don't have to use__ the hairdryer before you go out.\nIt's warm and sunny today. We __don't have to wear__ coats.\nGeorge has got a stomachache. He __has to see__ a doctor. He can't play football today."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Поппи и Эммы и впиши have to в нужной форме", "mode": "type", "text": "Poppy: Emma, is that you? I can't hear you. You __have to speak__ (speak) louder.\nEmma: Yes, it's me. I've got a sore throat. That's why I didn't go to school. I think I __have to drink__ (drink) some more tea.\nPoppy: Oh dear. __Do__ you __have to see__ (see) a doctor?\nEmma: No, I __don't__. It's not really bad.\nPoppy: OK. I'm phoning because we __don't have to do__ (do) a French test on Wednesday. It's on Friday now. Our teacher told us at school today.\nEmma: That's good news. I __don't have to learn__ (learn) the new words on Tuesday. I can wait until Thursday.\nPoppy: I've got some more news. There's a new boy in our class. He's French.\nEmma: He's lucky! He __doesn't have to do__ (do) anything for the French test.\nPoppy: Ha ha! That's true. His French is perfect!"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши правдивые предложения о себе", "needs_review": true, "html": "<p>Четыре предложения с <b>have to</b> или <b>don’t have to</b>: что тебе приходится делать дома и в школе, а что делать не нужно.</p><p>Начни так: <i>On Monday I have to … At the weekend I don’t have to …</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Хорошая работа! have to и don’t have to больше не путаются.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 3';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 3', 2, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 2, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · should</h2><p>Сегодня — как дать совет и назвать мелкую травму.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай и выбери подходящее слово", "questions": [{"q": "Look at this big ___ on my leg. It’s from a football!", "type": "single", "correct": [1], "options": [{"text": "burn"}, {"text": "bruise"}, {"text": "bite"}]}, {"q": "I've got a ___. Luckily, I write with my left hand!", "type": "single", "correct": [2], "options": [{"text": "cut"}, {"text": "bite"}, {"text": "broken arm"}]}, {"q": "I've got a ___ on my hand. It's from a mosquito.", "type": "single", "correct": [0], "options": [{"text": "bite"}, {"text": "bruise"}, {"text": "burn"}]}, {"q": "I've got a ___ on my finger. I wasn't careful when I was making salad.", "type": "single", "correct": [1], "options": [{"text": "bruise"}, {"text": "cut"}, {"text": "bite"}]}, {"q": "This ___ on my hand is from hot soup.", "type": "single", "correct": [2], "options": [{"text": "broken arm"}, {"text": "cut"}, {"text": "burn"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини ситуацию с советом", "pairs": [{"left": "There are lots of mosquitoes.", "right": "You should use a net."}, {"left": "It's raining.", "right": "You should take an umbrella."}, {"left": "Dad has got a bad burn.", "right": "He should go to the doctor."}, {"left": "Maria has a temperature.", "right": "She should go to bed."}, {"left": "The weather is nice this weekend.", "right": "We should go camping."}, {"left": "I played football and now I have a bruise.", "right": "You should be careful next time."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь вопросы с should", "items": [{"words": ["Should", "I", "read", "this", "book?"], "sentence": "Should I read this book?", "prompt": "про книгу"}, {"words": ["Should", "David", "play", "football?"], "sentence": "Should David play football?", "prompt": "про Дэвида и футбол"}, {"words": ["Should", "we", "go", "to", "bed?"], "sentence": "Should we go to bed?", "prompt": "про сон"}, {"words": ["Should", "Penny", "have", "any", "cakes?"], "sentence": "Should Penny have any cakes?", "prompt": "про Пенни и пирожные"}, {"words": ["Should", "I", "phone", "my", "brothers?"], "sentence": "Should I phone my brothers?", "prompt": "про братьев"}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Впиши should или shouldn’t с глаголом: go · have · phone · play · read", "mode": "type", "text": "You __should read__ this book. It's great.\nDavid has got a broken arm. He __shouldn't play__ football.\nIt's 11.30 p.m. We __should go__ to bed.\nPenny has got a stomachache. She __shouldn't have__ any cakes.\nMy brothers are late. I __should phone__ them and ask where they are."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор доктора Кью и Милли и впиши should с глаголом", "mode": "type", "text": "Dr Q: I'm tired.\nMillie: You __should lie__ (lie) down.\nDr Q: I have lots of work and there's a good film on TV. But I've got a headache too.\nMillie: You __should turn__ (turn) off your computer and you __shouldn't watch__ (watch) TV.\nDr Q: OK.\nMillie: __Should I make__ (I / make) you some soup?\nDr Q: No, thanks. I'm not hungry. But I've got a sore throat now. __Should I drink__ (I / drink) some tea with honey?\nMillie: Yes, you __should__. I can make it.\nDr Q: Thank you, Millie."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Дай совет вслух и запиши ответ", "needs_review": true, "html": "<p>Твой одноклассник весь день сидит за компьютером, и у него болит голова. Дай ему три совета: два с <b>should</b> и один с <b>shouldn’t</b>.</p>", "sample": "", "sample_tts": {"text": "You shouldn't eat so many sweets.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_medal.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! Советовать по-английски ты уже умеешь.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 4';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
