  else
    update classroom_lessons set sort_order = 3, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · Как спросить о самочувствии</h2><p>Сегодня — как спросить, что случилось, и дать совет.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай реплику и выбери ответ", "questions": [{"q": "A: What's the matter?", "type": "single", "correct": [1], "options": [{"text": "Yes, you're right."}, {"text": "I don't feel very well."}, {"text": "Why don't you lie down?"}]}, {"q": "A: I have a burn.", "type": "single", "correct": [2], "options": [{"text": "I feel terrible."}, {"text": "What's the matter?"}, {"text": "Why don't you put some ice on it?"}]}, {"q": "A: I've got a headache.", "type": "single", "correct": [0], "options": [{"text": "Why don't you take a painkiller?"}, {"text": "What's wrong?"}, {"text": "I feel terrible."}]}, {"q": "A: I think you should see the dentist.", "type": "single", "correct": [1], "options": [{"text": "What's the matter?"}, {"text": "Yes, you're right."}, {"text": "I've got a cut."}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'order', $blk${"title": "Составь реплики разговора о здоровье", "items": [{"words": ["What's", "the", "matter?"], "sentence": "What's the matter?", "prompt": "вопрос о самочувствии"}, {"words": ["I", "feel", "terrible."], "sentence": "I feel terrible.", "prompt": "ответ"}, {"words": ["I've", "got", "a", "cut."], "sentence": "I've got a cut.", "prompt": "про порез"}, {"words": ["Why", "don't", "you", "put", "a", "plaster", "on", "it?"], "sentence": "Why don't you put a plaster on it?", "prompt": "совет про пластырь"}, {"words": ["I've", "got", "toothache."], "sentence": "I've got toothache.", "prompt": "про зубную боль"}, {"words": ["I", "think", "you", "should", "see", "the", "dentist."], "sentence": "I think you should see the dentist.", "prompt": "совет про дантиста"}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор Грега с папой и впиши по одному слову", "mode": "type", "text": "Dad: What's the __matter__?\nGreg: I feel __terrible__, Dad. __I've__ got a headache.\nDad: I think you __should__ take a painkiller.\nGreg: Yes, you're __right__.\nDad: __Why__ don't you lie down too?\nGreg: Yes, that's a good __idea__."}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай жалобу и впиши пропущенные слова в совет", "mode": "type", "text": "A: I've got a headache.\nB: I think you __should take__ a painkiller.\nA: I've got bad bruises on my legs.\nB: Why don't you __put__ some cream on them?\nA: I've got these mosquito bites.\nB: You should put __cream__ on them.\nA: I've got a burn on my hand.\nB: Why don't you put some __ice__ on it?\nA: I've got a sore throat.\nB: You should drink some __mint tea__."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши разговор с другом", "needs_review": true, "html": "<p>Твой лучший друг чувствует себя ужасно. Напиши ваш разговор: спроси, что случилось, выслушай ответ, дай два совета и получи согласие.</p><p>Используй слова: <b>idea · matter · right · should · terrible · well · why</b>.</p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Разыграй разговор и запиши ответ", "needs_review": true, "html": "<p>Твоя сестра обожгла руку о горячий чайник. Спроси, что случилось, посочувствуй и дай ей совет.</p>", "sample": "", "sample_tts": {"text": "What's the matter? You look terrible.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_thumb.webp\" alt=\"\" style=\"height:200px\"></p><p>Супер! Теперь ты знаешь, как поддержать и посоветовать.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 5';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 5', 4, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 4, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_girl_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · Reading</h2><p>Сегодня читаем блог Билла: что делают при простуде в разных странах.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>Bill’s blog · What should you do for a cold?</h3><p><b>1 England.</b> What should you do when you have a cold? My mum usually makes me a cup of hot tea. But some parents have different ideas. I asked my e-pals from different countries what they have to do when they don’t feel well.</p><p><b>2 Poland.</b> My friend Marek has to drink hot milk when he has a cold or a sore throat. His mum puts the milk with some butter in the microwave oven. When it’s hot, she adds an egg (not cooked!) and some honey. I don’t think it’s tasty, but he says it works.</p><p><b>3 Japan.</b> Aiko doesn’t have a hot drink for a cold, but her dad makes her hot soup. It’s actually hot green onion soup. Aiko says you should have three bowls of this soup every day when you have a cold. She says it’s good for a blocked nose too.</p><p><b>4 Canada.</b> My friend Charlie thinks socks are a good idea for a cold. He says you have to use old socks when you are ill! First, you have to put your feet in hot water, so they are warm. Then you put the socks in water, so they are wet. Next you put on the wet socks and wear some dry socks on top of them. Then go to bed!</p>"}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Прочитай блог и соедини человека с тем, что он делает", "pairs": [{"left": "Bill's mum", "right": "makes tea for a cold."}, {"left": "Marek has to", "right": "drink hot milk for a cold."}, {"left": "Aiko", "right": "doesn't have tea or milk for a cold."}, {"left": "Aiko's dad", "right": "makes hot soup for a cold."}, {"left": "Charlie", "right": "wears wet socks for a cold."}], "material": "<h3>Bill’s blog · What should you do for a cold?</h3><p><b>1 England.</b> What should you do when you have a cold? My mum usually makes me a cup of hot tea. But some parents have different ideas. I asked my e-pals from different countries what they have to do when they don’t feel well.</p><p><b>2 Poland.</b> My friend Marek has to drink hot milk when he has a cold or a sore throat. His mum puts the milk with some butter in the microwave oven. When it’s hot, she adds an egg (not cooked!) and some honey. I don’t think it’s tasty, but he says it works.</p><p><b>3 Japan.</b> Aiko doesn’t have a hot drink for a cold, but her dad makes her hot soup. It’s actually hot green onion soup. Aiko says you should have three bowls of this soup every day when you have a cold. She says it’s good for a blocked nose too.</p><p><b>4 Canada.</b> My friend Charlie thinks socks are a good idea for a cold. He says you have to use old socks when you are ill! First, you have to put your feet in hot water, so they are warm. Then you put the socks in water, so they are wet. Next you put on the wet socks and wear some dry socks on top of them. Then go to bed!</p>"}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай блог и выбери правильный ответ", "questions": [{"q": "Do all parents have the same ideas for a cold?", "type": "single", "correct": [1], "options": [{"text": "Yes, they do."}, {"text": "No, they don't."}]}, {"q": "How does Marek's mum make the milk hot?", "type": "single", "correct": [1], "options": [{"text": "She puts it in the fridge."}, {"text": "She puts it in the microwave oven."}, {"text": "She puts it in the sun."}]}, {"q": "Does Aiko's dad make her something hot for a cold?", "type": "single", "correct": [1], "options": [{"text": "No, he doesn't. He makes her cold tea."}, {"text": "Yes, he does. He makes her hot soup."}]}, {"q": "What do you need for Charlie's idea?", "type": "single", "correct": [2], "options": [{"text": "green onions and honey"}, {"text": "a net and a torch"}, {"text": "old socks and hot water"}]}, {"q": "How often should you have the soup, Aiko says?", "type": "single", "correct": [0], "options": [{"text": "three bowls every day"}, {"text": "one bowl a week"}, {"text": "two bowls on Sunday"}]}], "material": "<h3>Bill’s blog · What should you do for a cold?</h3><p><b>1 England.</b> What should you do when you have a cold? My mum usually makes me a cup of hot tea. But some parents have different ideas. I asked my e-pals from different countries what they have to do when they don’t feel well.</p><p><b>2 Poland.</b> My friend Marek has to drink hot milk when he has a cold or a sore throat. His mum puts the milk with some butter in the microwave oven. When it’s hot, she adds an egg (not cooked!) and some honey. I don’t think it’s tasty, but he says it works.</p><p><b>3 Japan.</b> Aiko doesn’t have a hot drink for a cold, but her dad makes her hot soup. It’s actually hot green onion soup. Aiko says you should have three bowls of this soup every day when you have a cold. She says it’s good for a blocked nose too.</p><p><b>4 Canada.</b> My friend Charlie thinks socks are a good idea for a cold. He says you have to use old socks when you are ill! First, you have to put your feet in hot water, so they are warm. Then you put the socks in water, so they are wet. Next you put on the wet socks and wear some dry socks on top of them. Then go to bed!</p>"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай блог ещё раз и впиши по одному слову", "mode": "type", "text": "Bill asked his __e-pals__ for ideas.\nMarek's idea works for a cold or a sore __throat__.\nBill thinks the milk drink isn't __tasty__.\nAiko's soup has green __onions__ in it.\nCharlie wears __wet__ and dry socks in bed.", "material": "<h3>Bill’s blog · What should you do for a cold?</h3><p><b>1 England.</b> What should you do when you have a cold? My mum usually makes me a cup of hot tea. But some parents have different ideas. I asked my e-pals from different countries what they have to do when they don’t feel well.</p><p><b>2 Poland.</b> My friend Marek has to drink hot milk when he has a cold or a sore throat. His mum puts the milk with some butter in the microwave oven. When it’s hot, she adds an egg (not cooked!) and some honey. I don’t think it’s tasty, but he says it works.</p><p><b>3 Japan.</b> Aiko doesn’t have a hot drink for a cold, but her dad makes her hot soup. It’s actually hot green onion soup. Aiko says you should have three bowls of this soup every day when you have a cold. She says it’s good for a blocked nose too.</p><p><b>4 Canada.</b> My friend Charlie thinks socks are a good idea for a cold. He says you have to use old socks when you are ill! First, you have to put your feet in hot water, so they are warm. Then you put the socks in water, so they are wet. Next you put on the wet socks and wear some dry socks on top of them. Then go to bed!</p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай про части тела и перетащи слова в пропуски", "mode": "drag", "text": "Your __brain__ is a very important part of your body. You use it to think and it sends messages to all the other parts of your body. It tells your __heart__ to work, so the red __blood__ can go around your body. You also have lots of strong white __bones__ inside your body, so you can stand up. The __muscles__ hold them together and they make them move, so you can run and walk."}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши ответ Биллу", "needs_review": true, "html": "<p>Какой из четырёх способов ты бы попробовал и почему? И что делают при простуде в твоей семье? Четыре-пять предложений.</p><p>Начни так: <i>Hi Bill, I would like to try …</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_popper.webp\" alt=\"\" style=\"height:200px\"></p><p>Здорово! Блог прочитан, ответ Биллу написан.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 6';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 6', 5, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 5, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_highfive.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · Listening and Writing</h2><p>Сегодня слушаем разговор Карен с папой и пишем свою статью.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "LISTENING 🎧 Послушай разговор Карен с папой и впиши совет", "mode": "type", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A13.mp3", "text": "You __should study__ harder.\nYou __shouldn't play__ video games.\nYou should __go__ to bed early.\nYou should __put__ your calculator in your school bag.\nYou __have to eat__ when you study."}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "LISTENING 🎧 Послушай разговор ещё раз и выбери: верно, неверно или не сказано", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A13.mp3", "questions": [{"q": "Karen has a Maths test tomorrow.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Karen's mum is watching TV.", "type": "single", "correct": [2], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Karen doesn't like Maths.", "type": "single", "correct": [2], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "She was studying when her dad came home.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "She has to go to bed at 9.30 p.m.", "type": "single", "correct": [1], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}, {"q": "Karen's dad made her some food.", "type": "single", "correct": [0], "options": [{"text": "Верно"}, {"text": "Неверно"}, {"text": "Не сказано"}]}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "LISTENING 🎧 Карен рассказывает всё подруге. Впиши по одному слову", "mode": "type", "audio": "https://api.wowteach.ru/storage/v1/object/public/classroom-media/gg3%20wb/GG%20L3%20WkBk%20A13.mp3", "text": "Karen: Hi __Maria__. I'm sorry, but I can't come to your house and finish the __history__ project.\nMaria: Why not?\nKaren: I have to study Maths. I'm not __ready__ for the test because I was playing video __games__ when my dad came home.\nMaria: Oh dear. Does your dad know?\nKaren: Yes! Now I have to study all evening. But he says I shouldn't study after __nine__ o'clock and then I should relax before I go to bed at __ten__ o'clock.\nMaria: OK. Sleep well! See you tomorrow!"}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<h3>Get ready to go on a camping holiday</h3><p><b>Do you want to go on a camping holiday this summer?</b></p><p>It is often cold at night in a tent. You have to take warm clothes like a hoodie, not just T-shirts and shorts. Take boots too because it sometimes rains. Learn how to put up your tent before you go. It isn’t always easy. There are lots of mosquitoes in the countryside on summer nights. You should take a net. Then you don’t have to worry about bites. You should also take a torch. It is usually dark on campsites at night, so a torch is useful!</p>"}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини вещь с тем, зачем её берут в поездку за город", "pairs": [{"left": "money", "right": "to buy a souvenir or a snack"}, {"left": "sandwiches", "right": "you shouldn't be hungry when you walk a lot"}, {"left": "a camera", "right": "to take photos of birds, trees and your friends"}, {"left": "a hoodie", "right": "you don't have to worry about mosquito bites"}], "material": "<h3>Get ready to go on a camping holiday</h3><p><b>Do you want to go on a camping holiday this summer?</b></p><p>It is often cold at night in a tent. You have to take warm clothes like a hoodie, not just T-shirts and shorts. Take boots too because it sometimes rains. Learn how to put up your tent before you go. It isn’t always easy. There are lots of mosquitoes in the countryside on summer nights. You should take a net. Then you don’t have to worry about bites. You should also take a torch. It is usually dark on campsites at night, so a torch is useful!</p>"}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'task', $blk${"title": "WRITING ✍️ Напиши статью о поездке за город", "needs_review": true, "html": "<p>Напиши свою статью: как подготовиться к поездке за город. Шесть-семь предложений.</p><p>Возьми за образец статью Беллы и слова из задания про вещи. Используй <b>have to</b>, <b>don’t have to</b>, <b>should</b>, <b>shouldn’t</b> и повелительные формы (<i>Take …, Learn …</i>).</p><p>Начни так: <i>Do you want to go to the countryside this summer?</i></p>"}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_certificate.webp\" alt=\"\" style=\"height:200px\"></p><p>Отлично! И послушали, и статью написали.</p>"}$blk$::jsonb, 7);
end $$;

do $$
declare v_lesson uuid;
begin
  select id into v_lesson from classroom_lessons
   where unit_id = 'a2bbdc71-5c49-451a-88cd-b5b4cea4d17b' and title = 'Homework 7';
  if v_lesson is null then
    insert into classroom_lessons (unit_id, title, sort_order, kind, is_published)
    values ('a2bbdc71-5c49-451a-88cd-b5b4cea4d17b', 'Homework 7', 6, 'homework', false) returning id into v_lesson;
  else
    update classroom_lessons set sort_order = 6, kind = 'homework' where id = v_lesson;
    delete from classroom_blocks where lesson_id = v_lesson;
  end if;
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/hello_teen_wave.webp\" alt=\"\" style=\"height:200px\"></p><h2>Unit 5 · Check yourself!</h2><p>Повторяем весь юнит перед тестом.</p>"}$blk$::jsonb, 0);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай описание и выбери, что у человека болит", "questions": [{"q": "Mum is in the garden and she is sneezing all the time. She has got …", "type": "single", "correct": [0], "options": [{"text": "a runny nose"}, {"text": "a temperature"}, {"text": "a sore throat"}]}, {"q": "Aunt Jane is lying on the sofa and holding her stomach. She has got …", "type": "single", "correct": [2], "options": [{"text": "a mosquito bite"}, {"text": "a blocked nose"}, {"text": "a stomachache"}]}, {"q": "Lara is in bed and the thermometer says 38.5°. She has got …", "type": "single", "correct": [0], "options": [{"text": "a temperature"}, {"text": "a runny nose"}, {"text": "a cough"}]}, {"q": "Uncle Joe is holding his cheek and he can't eat anything. He has got …", "type": "single", "correct": [0], "options": [{"text": "toothache"}, {"text": "a cold"}, {"text": "a blocked nose"}]}, {"q": "Gary is drinking tea with honey and he can hardly speak. He has got …", "type": "single", "correct": [1], "options": [{"text": "a cough"}, {"text": "a sore throat"}, {"text": "earache"}]}]}$blk$::jsonb, 1);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'match', $blk${"title": "Соедини начало и конец предложения", "pairs": [{"left": "Mum has to", "right": "go to the doctor."}, {"left": "I don't", "right": "have to do my homework now."}, {"left": "Does", "right": "Fred have to leave?"}, {"left": "Do you", "right": "have to learn these words?"}, {"left": "Stan and Archie", "right": "don't have to study today."}]}$blk$::jsonb, 2);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'quiz', $blk${"title": "Прочитай разговор и выбери правильное слово", "questions": [{"q": "A: I feel terrible. — B: What's ___ matter?", "type": "single", "correct": [0], "options": [{"text": "the"}, {"text": "a"}]}, {"q": "A: I've got a stomachache. — B: I think you ___ have some mint tea.", "type": "single", "correct": [0], "options": [{"text": "should"}, {"text": "shouldn't"}]}, {"q": "A: Yes, you're ___.", "type": "single", "correct": [1], "options": [{"text": "idea"}, {"text": "right"}]}, {"q": "B: Why ___ you go to bed too?", "type": "single", "correct": [1], "options": [{"text": "should"}, {"text": "don't"}]}, {"q": "A: OK. That's a good ___.", "type": "single", "correct": [0], "options": [{"text": "idea"}, {"text": "right"}]}]}$blk$::jsonb, 3);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'gaps', $blk${"title": "Прочитай разговор и впиши should в нужной форме", "mode": "type", "text": "A: You look tired. You __should lie down__ (lie down).\nB: I know. I feel terrible. __Should I see__ (I / see) the doctor?\nA: Don't be silly! Do you have a temperature?\nB: No, I don't.\nA: Then you __shouldn't go__ (not go) to the doctor. You're just tired. You __should sleep__ (sleep) in bed.\nB: OK. Can you phone Mark? He __shouldn't visit__ (not visit) me today.\nA: OK. __Should he call__ (he / call) you tomorrow?\nB: Yes. Thanks. You're a good friend."}$blk$::jsonb, 4);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'exact_input', $blk${"title": "Прочитай предложение и напиши слово по-английски", "items": [{"prompt": "There are muscles and b… inside your arms and legs. (кости)", "accept": ["bones", "Bones"]}, {"prompt": "Your b… is in your head and you use it to think. (мозг)", "accept": ["brain", "Brain"]}, {"prompt": "Your h… makes your blood move round your body. (сердце)", "accept": ["heart", "Heart"]}, {"prompt": "Tom fell badly and he went to hospital. His leg is b… and he's got some bruises. (сломана)", "accept": ["broken", "Broken"]}, {"prompt": "Be careful in the kitchen. You can get a burn from hot food and a c… from a knife. (порез)", "accept": ["cut", "a cut", "Cut"]}]}$blk$::jsonb, 5);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'speaking', $blk${"title": "SPEAKING 🎤 Расскажи вслух и запиши ответ", "needs_review": true, "html": "<p>Расскажи про день, когда ты болел: что у тебя болело, что тебе пришлось делать, какие советы тебе дали дома. Четыре-пять предложений.</p>", "sample": "", "sample_tts": {"text": "Last winter my sister had the flu and she had to stay in bed for a week.", "voice": "en_GB-alba"}}$blk$::jsonb, 6);
  insert into classroom_blocks (lesson_id, type, payload, sort_order)
  values (v_lesson, 'text', $blk${"html": "<p><img src=\"https://classroom.wowteach.ru/media/shared/gg/bye_trophy.webp\" alt=\"\" style=\"height:200px\"></p><p>Юнит пройден! Можно браться за тест.</p>"}$blk$::jsonb, 7);
end $$;
